function createShapeStack(x, y, w) {
	let p = random(palettes);
	let clr = shuffle([...p], true);
	let shapeCount = 5;
	push();
	translate(x, y);
	noStroke();
	for (let i = 0; i < shapeCount; i++) {
		let ww = map(i, 0, shapeCount, w, 0);
		let clrIndex = i % clr.length;
		shapes.push(new ShapeShifter(x, y, ww * 0.8, clr[clrIndex]));
	}
	pop();
}

function drawPrimitive(x, y, w, angle, shapeType) {
	push();
	translate(x, y);
	rotate(angle);

	if (shapeType === 0) {
		circle(0, 0, w);
	}
	else if (shapeType === 1) {
		square(0, 0, w);
	}
	else if (shapeType === 2) {
		rect(0, 0, w, w * 0.5);
		rect(0, 0, w * 0.5, w);
	}
	else if (shapeType === 3) {
		beginShape();
		vertex(-w / 2, -w / 2);
		vertex(w / 2, w / 2);
		vertex(-w / 2, w / 2);
		endShape(CLOSE);
	}
	else if (shapeType === 4) {
		rotate(PI / 4);
		square(0, 0, w * 0.7);
	}
	else if (shapeType === 5) {
		rotate(PI / 4);
		rect(0, 0, w, w * 0.25);
		rect(0, 0, w * 0.25, w);
	}
	pop();
}

function generateGrid(x, y, w, n) {
	let cellW = w / n;
	let margin = w * 0.04;
	let counter = 0;
	for (let j = 0; j < n; j++) {
		for (let i = 0; i < n; i++) {
			let cellX = i * cellW + (cellW / 2) + x - (w / 2);
			let cellY = j * cellW + (cellW / 2) + y - (w / 2);
			createShapeStack(cellX, cellY, cellW);
			counter++;
		}
	}
}


/*------------------------------------------------------------------------------------------*/


class ShapeShifter {
	constructor(x, y, w, clr) {
		this.x = x;
		this.y = y;
		this.w = w;
		this.clr = clr;
		this.regenerate();
	}

	display() {
		if (!this.exist) return;
		noStroke();
		fill(this.clr);
		drawPrimitive(this.x, this.y, this.w, this.angle, this.shapeType);
	}

	update() {
		if (random() < 0.004) this.regenerate();
	}

	regenerate() {
		this.angle = int(random(4)) * (TAU / 4);
		this.shapeType = int(random(6));
		this.exist = random([0, 1, 1]);
	}

	run() {
		this.display();
		this.update();
	}
}

